// agent/lib/log.ts
function log(...args) {
  try {
    send({ type: "log", line: args.map((a) => typeof a === "string" ? a : JSON.stringify(a, null, 2)).join(" ") });
  } catch {
    console.log(...args);
  }
}
var ok = (...a) => log("[+]", ...a);

// agent/lib/mem.ts
var mainModule = () => Process.enumerateModules()[0];
var moduleByPattern = (re) => Process.enumerateModules().find((m) => re.test(m.name));
var rP = (p) => {
  try {
    const v = p.readPointer();
    return v.isNull() ? null : v;
  } catch {
    return null;
  }
};
var rU16 = (p) => {
  try {
    return p.readU16();
  } catch {
    return null;
  }
};
var rU32 = (p) => {
  try {
    return p.readU32();
  } catch {
    return null;
  }
};
var rF = (p) => {
  try {
    return p.readFloat();
  } catch {
    return null;
  }
};
var rD = (p) => {
  try {
    return p.readDouble();
  } catch {
    return null;
  }
};

// agent/lib/ue/reflection.ts
var cachedMod = null;
function gameModule() {
  return cachedMod ??= moduleByPattern(/-Win64-Shipping\.exe$/i) ?? mainModule();
}
var inModule = (p) => {
  if (!p) return false;
  const m = gameModule();
  return p.compare(m.base) >= 0 && p.compare(m.base.add(m.size)) < 0;
};
var O = {
  CLASS: 16,
  NAME: 24,
  OUTER: 32,
  FLAGS: 8,
  SUPER: 64,
  CHILDREN: 72,
